def generated_loss(batch, model_output, extra):
    alpha = float(extra.get('alpha', 1.0))
    logit = alpha * (batch['log_prob_w'] - batch['log_prob_l'])
    w = batch.get('weight')
    loss = -ops.logsigmoid(logit)
    if w is not None:
        loss = loss * w
    return loss.mean()

